let pArr=[];

function setup() {
	createCanvas(540, 540);
	background(0,12,33);
	angleMode(DEGREES);
	ellipseMode(CENTER);
	noStroke();
	for (let i = 0; i <360; i++){
		pArr.push(new Mover(random(width), random(height), width/256, color(random(172, 255), 64))); //parameters are x position, y position, size, and greyscale color
	}
}

function draw() {
//background(0,12,33);
	for (let p of pArr) { 
		p.move(); 
	}
}

class Mover {

constructor(x,y,size,color){
	this.x=x; 
	this.y=y; 
	this.sizeReference = size; 
	this.size = size/2;
	this.xSpeed = size/2;
	this.ySpeed = size/2;
	this.color = color;
	this.w = round(width);
	this.h = round(height);
	this.px = x;
	this.py = y;
}

		move(){
		 this.x+=this.xSpeed*Math.cos((this.x/this.px)/(this.w+this.py)-this.x/180)
		this.wrap();
		this.x+=this.xSpeed*(Math.cos((this.px*(this.x))/(this.w*this.py)));
		this.wrap();
    this.y+=this.ySpeed*Math.sin((this.y/this.py)/(this.h+this.px)-this.y/180)
		this.wrap();
    this.y+=this.ySpeed*(Math.sin((this.py*(this.y))/(this.h*this.px)));
		this.wrap();
		this.px = this.x;
		this.py= this.y;
		fill(this.color); 
		ellipse(this.x, this.y, this.size*width/256, this.size*height/256);
	}

	wrap(){
		if (this.x > width) this.x = this.size*1.5;
		if (this.x < 0) this.x = width-this.size*1.5;
		if (this.y > height) this.y = this.size*1.5;
		if (this.y < 0) this.y = height-this.size*1.5;
	}
}

